class FileOwnerChannel:
    """Write the code to HAI_OWNER_HOME — a directory the agent must not be able to read."""

    name = "file"

    def __init__(self, owner_home: Path, hai_home: Path) -> None:
        self.owner_home = owner_home
        self.hai_home = hai_home

    def deliver(self, challenge: dict[str, Any], code: str) -> dict[str, Any]:
        owner_home = real_path(self.owner_home)
        hai_home = real_path(self.hai_home)
        if owner_home == hai_home or hai_home in owner_home.parents:
            raise OwnerChannelError(
                "HAI_OWNER_HOME is inside HAI_HOME; the agent could read every code. "
                "Point HAI_OWNER_HOME to a directory the agent cannot read."
            )
        owner_home.mkdir(parents=True, exist_ok=True, mode=0o700)
        try:
            os.chmod(owner_home, 0o700)
        except OSError:
            pass

def http_bind_allowed(host: str, token: str | None = None) -> tuple[bool, str]:
    """Fail-closed bind policy: non-loopback hosts require a non-empty bearer token."""
    normalized = str(host or "").strip().lower()
    if not normalized:
        return False, "host is required"
    if normalized in LOOPBACK_HOSTS:
        return True, ""
    if token and str(token).strip():
        return True, ""
    return False, "non-loopback HTTP bind requires HAI_HTTP_TOKEN"


def verify_bearer_token(authorization: str | None, expected_token: str) -> bool:
    if not authorization or not str(authorization).startswith("Bearer "):
        return False
    provided = authorization[7:].strip()
    if not provided or not expected_token:
        return False
    return hmac.compare_digest(provided, expected_token)


def http_token_from_env() -> str | None:
    raw = os.environ.get("HAI_HTTP_TOKEN", "").strip()
    return raw or None

def strict_int(value: Any, name: str, *, min_value: int | None = None) -> tuple[int | None, dict[str, Any] | None]:
    if not isinstance(value, int) or isinstance(value, bool):
        return None, _invalid(name, "must be a literal integer")
    if min_value is not None and value < min_value:
        return None, _invalid(name, f"must be >= {min_value}")
    return value, None

def assert_under(path: Path, root: Path) -> Path:
    """Resolve *path* and ensure its real path stays under *root* (symlink-safe)."""
    resolved = real_path(path.expanduser())
    root_r = real_path(root)
    try:
        resolved.relative_to(root_r)
    except ValueError as exc:
        raise PathError(
            "path_outside_root",
            f"path {resolved} is outside allowed root {root_r}",
            path=str(resolved),
            root=str(root_r),
        ) from exc

